),
led AS (SELECT migration_name AS name, checksum FROM "_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL),
onmain AS (SELECT l.name, l.checksum, bool_or(v.edited) AS edited FROM led l JOIN v ON v.name = l.name GROUP BY l.name, l.checksum),
cls AS (
  SELECT o.name, o.edited,
         CASE WHEN EXISTS (SELECT 1 FROM v WHERE v.name = o.name AND v.kind = 'current_lf' AND v.sum = o.checksum) THEN 'same'
              WHEN EXISTS (SELECT 1 FROM v WHERE v.name = o.name AND v.kind = 'current_crlf' AND v.sum = o.checksum) THEN 'current_crlf'
              WHEN EXISTS (SELECT 1 FROM v WHERE v.name = o.name AND v.kind = 'earlier_lf' AND v.sum = o.checksum) THEN 'earlier_lf'
              WHEN EXISTS (SELECT 1 FROM v WHERE v.name = o.name AND v.kind = 'earlier_crlf' AND v.sum = o.checksum) THEN 'earlier_crlf'
              ELSE 'unexplained' END AS c
  FROM onmain o),
lines(n, flag, observed_count) AS (
            SELECT 1, (SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname = current_user), NULL::bigint
  UNION ALL SELECT 2, NULL, (SELECT count(*) FROM cls)
  UNION ALL SELECT 3, NULL, (SELECT count(*) FROM cls WHERE c = 'same')
  UNION ALL SELECT 4, NULL, (SELECT count(*) FROM cls WHERE c <> 'same')
  UNION ALL SELECT 5, NULL, (SELECT count(*) FROM cls WHERE NOT edited AND c <> 'same')
  UNION ALL SELECT 6, NULL, (SELECT count(*) FROM cls WHERE NOT edited AND c = 'current_crlf')
  UNION ALL SELECT 7, NULL, (SELECT count(*) FROM cls WHERE NOT edited AND c = 'unexplained')
  UNION ALL SELECT 8, NULL, (SELECT count(*) FROM cls WHERE edited AND c <> 'same')
  UNION ALL SELECT 9, NULL, (SELECT count(*) FROM cls WHERE edited AND c = 'current_crlf')
  UNION ALL SELECT 10, NULL, (SELECT count(*) FROM cls WHERE edited AND c = 'earlier_lf')
  UNION ALL SELECT 11, NULL, (SELECT count(*) FROM cls WHERE edited AND c = 'earlier_crlf')
  UNION ALL SELECT 12, NULL, (SELECT count(*) FROM cls WHERE edited AND c = 'unexplained')
  UNION ALL SELECT 13, (SELECT count(*) FROM cls WHERE c = 'unexplained') = 0, NULL
  UNION ALL SELECT 14, NULL, (SELECT count(*) FROM "_prisma_migrations" WHERE migration_name IN
                                ('20261107090000_accountant_ops_monitor', '20261107091000_accountant_delivery_complained', '20261107092000_accountant_ops_admin_read'))
)
SELECT n, flag, observed_count FROM lines ORDER BY n;

