led AS (SELECT migration_name AS name, checksum FROM "_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL)
SELECT left(l.name, 6)::int AS yyyymm, bool_or(v.edited) AS edited, count(DISTINCT l.name) AS unexplained
  FROM led l JOIN v ON v.name = l.name
 WHERE NOT EXISTS (SELECT 1 FROM v x WHERE x.name = l.name AND x.sum = l.checksum)
 GROUP BY 1 ORDER BY 1;

